import {compareSavedVersions,savedFrameEntries} from './change-diff.js';
export function installChangePage({root,openSequence,openProp,toast}){
 root.innerHTML=`<div class="changes-heading"><div><h1>Asset changes</h1><p>Exact saved versions awaiting integration. Later edits create a fresh pending item.</p></div><button id="changes-refresh">Refresh saved changes</button><button id="changes-repair">Repair missing journal entries</button></div><div class="change-filters"><button data-change-status="pending">Pending</button><button data-change-status="completed">Completed</button><button data-change-status="deferred">Deferred</button><label><input id="changes-earlier" type="checkbox"> Show earlier pending versions</label><input id="changes-search" type="search" placeholder="Find a sequence or prop" aria-label="Find an asset change"></div><p id="changes-status" role="status"></p><div class="changes-layout"><div id="changes-list"></div><section id="change-inspect"><p>Pick an item to inspect its saved pixels and metadata.</p></section></div>`;
 const $=s=>root.querySelector(s);let entries=[],filter='pending',current=null;
 const el=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
 async function api(path,options={}){const response=await fetch('/api/changes'+path,{...options,headers:{'Content-Type':'application/json',...options.headers}}),value=await response.json();if(!response.ok)throw Error(value.error||'Change tracking unavailable.');return value;}
 async function refresh(){try{$('#changes-status').textContent='Reading saved versions…';entries=[];let cursor;do{const page=await api(cursor?'?cursor='+encodeURIComponent(cursor):'');entries.push(...page.changes);cursor=page.cursor;}while(cursor);entries.sort((a,b)=>b.at.localeCompare(a.at));render();$('#changes-status').textContent=`${entries.length} saved versions · drafts appear after a successful save. Completion records the exact version and implementation reference.`;}catch(e){$('#changes-status').textContent=e.message;}}
 function render(){const latest=new Map();for(const e of entries)if(!latest.has(e.kind+e.entityId))latest.set(e.kind+e.entityId,e.id);const visible=entries.filter(e=>e.receipt.status!=='pending'||$('#changes-earlier').checked||latest.get(e.kind+e.entityId)===e.id);const list=$('#changes-list'),query=$('#changes-search').value.toLowerCase();list.replaceChildren();for(const b of root.querySelectorAll('[data-change-status]')){const count=visible.filter(e=>e.receipt.status===b.dataset.changeStatus).length;b.textContent=b.dataset.changeStatus[0].toUpperCase()+b.dataset.changeStatus.slice(1)+' · '+count;b.setAttribute('aria-pressed',String(filter===b.dataset.changeStatus));}document.querySelector('#change-count').textContent=visible.filter(e=>e.receipt.status==='pending').length||'';
 for(const e of visible.filter(e=>e.receipt.status===filter&&(e.name+' '+e.entityId).toLowerCase().includes(query))){const b=el('button');b.className='change-item';b.setAttribute('aria-pressed',String(current?.id===e.id));b.append(el('strong',e.name),el('small',`${e.kind} · ${new Date(e.at).toLocaleString()} · ${e.versionHash.slice(0,10)}`),el('small',e.kind==='tree'?`${e.summary.components} components · ${e.summary.editedComponents} changed · ${e.summary.mode==='recipe'?'code '+e.summary.code:'seed '+e.summary.seed}`:['sequence','climb'].includes(e.kind)?`${e.summary.frames} frames · ${e.summary.editedFrames} changed/new pixel grids`:`${e.summary.width}×${e.summary.height} · revision ${e.summary.revision}`));b.onclick=()=>inspect(e.id);list.append(b);}if(!list.children.length)list.append(el('p','No matching '+filter+' changes.'));
 }
 function preview(rows,palette=null,before=null){const c=el('canvas'),w=palette?rows[0].length:24,h=rows.length;c.width=w;c.height=h;const x=c.getContext('2d');for(let y=0;y<h;y++)for(let i=0;i<w;i++){const colour=palette?rows[y][i]:rows[y][i]==='.'?null:rows[y][i]==='R'?'#e86458':'#19222b';if(colour){x.fillStyle=colour;x.fillRect(i,y,1,1);}if(before&&rows[y][i]!==before[y]?.[i]){x.fillStyle='#49b4e477';x.fillRect(i,y,1,1);}}return c;}
 async function inspect(id){try{current=await api('/'+id);render();const e=current,panel=$('#change-inspect');panel.replaceChildren(el('h2',e.name),el('p',`${e.kind} · ${e.entityId}`),el('p','Version '+e.versionHash));const strip=el('div');strip.className='change-preview-strip';if(e.kind==='tree'){for(const c of e.snapshot.components){const item=el('div');item.append(preview(c.rows.map(row=>[...row].map(t=>t==='.'?null:e.snapshot.palette[t])),true),el('small',c.name+' · '+c.width+'×'+c.height+' · '+c.origin+' · revision '+c.revision));strip.append(item);}}else if(['sequence','climb'].includes(e.kind)){savedFrameEntries(e.snapshot).forEach(({frame:f,index:i,sequence})=>{const item=el('div');item.append(preview(f.rows),el('small',`${e.kind==='climb'?({climb:'Climb',front:'Rotate front',back:'Rotate behind','centre-front':'Centred front','centre-back':'Centred behind'}[sequence])+' · ':''}${i+1} · ${f.role||'cycle'} · ${f.durationMs??f.ms} ms${e.kind==='climb'?' / +'+f.gain+' cells':''} · ${f.origin}`));const before=savedFrameEntries(e.previous).find(p=>p.frame.id===f.id)?.frame;if(before){const diff=f.rows.reduce((n,r,y)=>n+[...r].filter((v,x)=>v!==before.rows[y]?.[x]).length,0);item.append(el('small',diff+' pixel changes'));}strip.append(item);});}else strip.append(preview(e.snapshot.pixels,true),el('p',`${e.snapshot.width}×${e.snapshot.height} · ${e.snapshot.origin} · revision ${e.snapshot.revision}`));panel.append(strip);if(e.snapshot.defaultProposal){const proposal=e.snapshot.defaultProposal;panel.append(el('h3','Proposed slider defaults - pending review'),el('p','Baselines for individual behaviour modifiers, not fixed animation scripts.'));for(const [id,value]of Object.entries(proposal.values)){const definition=proposal.definitions?.[id];panel.append(el('p',(definition?.label||id)+': '+value+' '+(definition?.unit||'')+' (system '+proposal.systemValues[id]+' '+(definition?.unit||'')+')'));}}if(['sequence','climb','tree'].includes(e.kind)){const diff=compareSavedVersions(e.previous,e.snapshot),details=el('details');details.append(el('summary','Exact change summary: pixels, timing, anchors, gaze, tracks and metadata'),el('pre',JSON.stringify(diff,null,2)));panel.append(details);}if(e.kind==='prop'&&e.snapshot.behaviourNotes){panel.append(el('h3','Behaviour / animation notes'),el('pre',e.snapshot.behaviourNotes));}
 const open=el('button',e.kind==='tree'?'Open cat-tree workshop':e.kind==='climb'?'Open climb workbench':['sequence','climb'].includes(e.kind)?'Open current sequence':'Open props catalogue');open.onclick=()=>e.kind==='tree'?window.open('http://127.0.0.1:8769/prototype/tree-lab.html','_blank','noopener'):e.kind==='climb'?window.open('http://127.0.0.1:8769/prototype/climb-lab.html','_blank','noopener'):e.kind==='sequence'?openSequence(e.entityId):openProp(e.entityId,e.name);panel.append(open,el('p','The review above is this saved version. The editor may contain newer work.'));
 const notes=el('textarea');notes.value=e.receipt.notes||'';notes.placeholder='What was integrated, inspected or deferred?';notes.maxLength=2000;notes.setAttribute('aria-label','Integration notes');const reference=el('input');reference.value=e.receipt.reference||'';reference.placeholder='Build, commit, catalogue or audit reference';reference.maxLength=500;reference.setAttribute('aria-label','Implementation reference');panel.append(notes,reference);
 for(const [status,label] of [['completed','Move to completed'],['deferred','Defer for later'],['pending','Return to pending']]){const b=el('button',label);b.onclick=async()=>{try{await api('/'+e.id,{method:'PUT',body:JSON.stringify({versionHash:e.versionHash,status,notes:notes.value,reference:reference.value})});filter=status;await refresh();await inspect(e.id);}catch(error){toast(error.message);}};panel.append(b);}
 const metadata=el('details');metadata.append(el('summary','Exact saved metadata / pixels'),el('pre',JSON.stringify({snapshot:e.snapshot,receipt:e.receipt},null,2)));panel.append(metadata);
 }catch(e){toast(e.message);}}
 $('#changes-refresh').onclick=refresh;$('#changes-repair').onclick=async()=>{try{$('#changes-repair').disabled=true;await api('/bootstrap',{method:'POST'});await refresh();}catch(e){toast(e.message);}finally{$('#changes-repair').disabled=false;}};$('#changes-search').oninput=render;$('#changes-earlier').onchange=render;for(const b of root.querySelectorAll('[data-change-status]'))b.onclick=()=>{filter=b.dataset.changeStatus;render();};window.addEventListener('studio-asset-saved',()=>{if(!root.hidden)refresh();});setInterval(()=>{if(!document.hidden&&!root.hidden)refresh();},15000);return {open:refresh};
}
